INSERT INTO `house` VALUES (1,'杭州','临安','临安','南苑小区',NULL,119.725459,30.234353,68.50,2,1,2,'LOW',6,'[\"S\"]','FINE',0,'RESIDENTIAL','SLAB','FLAT','BRICK_CONCRETE','COMMERCIAL',NULL,'2021-04-30',NULL,1280000.00,'\n                    自住装修，带30方露台，二室一厅两卫\n                  ','\n                    小区是老小区，今年刚刚改造好，和新的小区一样，车位充足，绿化做的很漂亮，物业管理升级\n                  ','\n                    小区南边100米有多家银行，大型市，小区东北面200米有电影院，500米有人民医院\n                  ','103000000000','ON_SALE',1,'2026-10-16 21:50:06','2026-10-22 10:49:38',1,'VERIFIED','LEGACY_IMPORT','LEGACY_IMPORT',0,0,'2026-10-16 21:50:06','2026-10-22 10:49:38'),(2,'杭州','西湖','翠苑','翠苑四区',NULL,120.127871,30.293387,70.20,3,1,1,'HIGH',6,'[\"S\"]','SIMPLE',0,'RESIDENTIAL','SLAB','FLAT','BRICK_CONCRETE','COMMERCIAL',NULL,'2020-10-07',NULL,2760000.00,'\n                    翠苑四区东临农灌河、西至古翠路、南靠文二路、北与文一路相接。房屋建筑上合理，每幢之间相隔近几十米，视眼辽阔，且幢与幢间都有樟树相隔，既净化空气，又美化环境。而且大门口进来处还有个小公园\n                  ','\n                    小区出门往南50米是省立同德医院。北面200米古翠路地铁站。地铁上建联华*市。 正北文一路北面物美*市，电影院吃喝玩乐俱全。\n                  ','\n                    地铁2号线，公交车：19K19、43K43、70K70、156K156、K209（夜间线）、K211（夜间线）等等，B2助你快速出行\n                  ','103000000000','ON_SALE',8,'2026-10-16 21:50:06','2026-10-22 10:49:38',2,'VERIFIED','LEGACY_IMPORT','LEGACY_IMPORT',0,0,'2026-10-16 21:50:06','2026-10-22 10:49:38'),(3,'杭州','上城','采荷','清泰小区',NULL,120.198660,30.254390,78.24,2,2,1,'HIGH',7,'[\"S\", \"N\"]','SIMPLE',0,'RESIDENTIAL','SLAB_TOWER','FLAT','STEEL_CONCRETE','COMMERCIAL',NULL,'2019-08-16',NULL,4250000.00,'\n                    此房户型正气 两房朝南 一房朝北 进门是厅宽敞明亮 带窗户 厨房朝北带窗户 卫生间也有窗户 房子是一梯两户的比较清爽的。\n                  ',NULL,NULL,'103000000000','ON_SALE',1,'2026-10-16 21:50:06','2026-10-22 10:49:38',1,'VERIFIED','LEGACY_IMPORT','LEGACY_IMPORT',0,0,'2026-10-16 21:50:06','2026-10-22 10:49:38'),(4,'杭州','上城','复兴','蓝江公寓',NULL,120.178313,30.215905,146.20,4,1,2,'LOW',11,'[\"S\"]','SIMPLE',1,'RESIDENTIAL','SLAB_TOWER','FLAT','BRICK_CONCRETE','COMMERCIAL',119.48,'2020-11-07',NULL,5990000.00,'\n                    业主对首付无要求，商贷公积金均可，售房原因为处理多余房产，诚心出售。\n                  ',NULL,'\n                    地铁四号线，复兴路站，南星桥站四号线和五号线 公交站有198,196，和62等。 出行方便\n                  ','103000000000','ON_SALE',9,'2026-10-16 21:50:06','2026-10-22 10:49:38',2,'VERIFIED','LEGACY_IMPORT','LEGACY_IMPORT',0,0,'2026-10-16 21:50:06','2026-10-22 10:49:38'),(5,'杭州','西湖','文教','白荡海人家',NULL,120.149216,30.296618,120.98,4,2,2,'MIDDLE',7,'[\"S\"]','SIMPLE',0,'RESIDENTIAL','SLAB','FLAT','MIXED','COMMERCIAL',NULL,'2021-06-29',NULL,8200000.00,'\n                    文一街板块较新较大的小区。开发商是坤和建设。物业是绿景物业！环境优美。这个小区分一期和二期还有三期，一期是1-14幢和23幢，1999年建成。二期是15幢A,B座，18.19.20.21.22这6幢电梯房，建成于2000年，16,17,24.25这4幢是三期，2002年建成。\n                  ','\n                    小区西面有物美；北面有大悦城综合体； 南面有沈塘桥地铁口； 出门就是白荡海公交车站和文一路隧道；生活便利，交通便捷\n                  ','\n                    一清新村公交站，白荡海公交站，打索桥站，沈塘桥站，下宁桥站。小区前有文一路隧道\n                  ','103000000000','ON_SALE',8,'2026-10-16 21:50:06','2026-10-22 10:49:38',2,'VERIFIED','LEGACY_IMPORT','LEGACY_IMPORT',0,0,'2026-10-16 21:50:06','2026-10-22 10:49:38'),(6,'杭州','上城','火车东站','红街公寓',NULL,120.213023,30.300046,135.54,4,1,2,'LOW',18,'[\"S\"]','SIMPLE',1,'RESIDENTIAL','SLAB_TOWER','FLAT','MIXED','COMMERCIAL',NULL,'2021-01-02',NULL,4750000.00,'\n                    此房是2010年交付使用的住宅，小区绿化和整体环境都很不错，有儿童乐游乐场，羽毛球场，，老年活动场所，等，物业改善过，龙湖物业，小区居住环境适宜。\n                  ','\n                    商场，汇合城商圈，九隆*市，华润万家，火车东站商圈等：银行；建设银行，农业银行，杭州合作银行；菜场，东明综合农贸市场；濮家综合农贸市场。\n                  ','\n                    红街公寓小区相邻火车东站，地铁1号线与4号线，同站换乘，室内出行方便，地铁直达。去市区，省外，高铁直达，火车出行，机场巴士直达萧山机场，都在杭州东站里面，小区西门口就是公交站台，出行便利。\n                  ','103000000000','ON_SALE',8,'2026-10-16 21:50:06','2026-10-22 10:49:38',2,'VERIFIED','LEGACY_IMPORT','LEGACY_IMPORT',0,0,'2026-10-16 21:50:06','2026-10-22 10:49:38'),(7,'杭州','滨江','白马湖','保亿风景蝶院观园',NULL,120.208436,30.176223,85.30,2,2,1,'MIDDLE',25,'[\"S\"]','FINE',1,'RESIDENTIAL','SLAB_TOWER','FLAT','STEEL_CONCRETE','COMMERCIAL',63.92,'2020-12-20',NULL,3500000.00,'\n                    保亿?风景蝶院位于滨江白马湖生态休闲文化圈，小区环境优雅，50米以上疏朗的楼间距，确保楼宇的通风采光及住户的私密性，80-90平刚需主力户型，24小时安保、监控安全保障，居住群体多为网易、阿里、华为等上市企业员工，整体素质高，物业管理严格，邻里和睦\n                  ','\n                    小区出西门为沿河公园，西向200米为月亮湾幼儿园，300米农贸市场，600米左右为滨江妇幼保健院，浙江中商*市，中国农业银行和工商银行，南向1公里为白马湖建国饭店，中国动漫博物馆以及风景秀丽的白马湖生态公园\n                  ','\n                    东邻江虹南路，北上经过华为和各类产业科技园，3公里到达龙湖天街和浙二医院，小区门北向东300米左右，张家西公交站可乘114路、177路、326路、1503路通达滨江大部分区域，驾车经彩虹快速路可通达复兴大桥和之江大桥\n                  ','103000000000','ON_SALE',4,'2026-10-16 21:50:06','2026-10-22 10:49:38',1,'VERIFIED','LEGACY_IMPORT','LEGACY_IMPORT',0,0,'2026-10-16 21:50:06','2026-10-22 10:49:38'),(8,'杭州','萧山','湘湖','美之园西区',NULL,120.251289,30.178903,138.22,4,2,2,'MIDDLE',6,'[\"S\"]','FINE',0,'RESIDENTIAL','SLAB_TOWER','FLAT','STEEL_CONCRETE','COMMERCIAL',120.00,'2020-06-20',NULL,3400000.00,'\n                    顺发美之园（美之园西区），在湘湖之滨，距萧山城区仅2千米. 顺发物业、健身房、停车位充足、户型都挺方正的、小区是由多层与小高层相结合的、环境幽静绿化很好\n                  ','\n                    农贸市场、宝贝尔美语幼儿园、小*市2个、早餐店、饭店、理发店、中国人民银行、水果店、修电脑店、spa店、文具店、面馆、杭州乐园、浪浪浪水上乐园\n                  ','\n                    小区门口有公共自行车可以使用、659路、712路公交车站、地铁一号线湘湖站(1330米）（米数取自百度地图)\n                  ','103000000000','ON_SALE',2,'2026-10-16 21:50:06','2026-10-22 10:49:38',1,'VERIFIED','LEGACY_IMPORT','LEGACY_IMPORT',0,0,'2026-10-16 21:50:06','2026-10-22 10:49:38'),(9,'杭州','富阳','江南新城','富春水岸',NULL,120.014882,30.008070,83.11,3,2,2,'MIDDLE',20,'[\"S\"]','ROUGH',1,'RESIDENTIAL','TOWER','FLAT','STEEL_CONCRETE','COMMERCIAL',NULL,'2020-10-21',NULL,1260000.00,'\n                    小区环境幽静，交通便利适合上班族，也适合老年人养老或者小孩居住\n                  ',NULL,NULL,'103000000000','ON_SALE',5,'2026-10-16 21:50:06','2026-10-22 10:49:38',1,'VERIFIED','LEGACY_IMPORT','LEGACY_IMPORT',0,0,'2026-10-16 21:50:06','2026-10-22 10:49:38'),(10,'杭州','上城','九堡','华鸿汇盛德堡',NULL,120.266547,30.320338,112.44,3,2,1,'HIGH',16,'[\"S\"]','FINE',1,'RESIDENTIAL','SLAB','FLAT','STEEL_CONCRETE','COMMERCIAL',93.48,'2020-06-08',NULL,3300000.00,'\n                    四季青服装市场，华贸鞋城，金海城购物广场，地铁东城广场，文化体育馆，农贸市场，浙大邵逸夫医院，江干区人民医院九堡分院