INSERT INTO `house_price_pred` VALUES (1,308,'452538d5-6314-4564-a486-5255dab0714a',1,'1.0','{\"city\": \"杭州\", \"halls\": 2, \"rooms\": 5, \"district\": \"滨江\", \"house_id\": \"308\", \"latitude\": 30.193899, \"bathrooms\": 2, \"longitude\": 120.157303, \"decoration\": \"SIMPLE\", \"request_id\": \"452538d5-6314-4564-a486-5255dab0714a\", \"floor_level\": \"HIGH\", \"orientation\": [\"S\"], \"has_elevator\": true, \"listing_date\": \"2021-08-17\", \"total_floors\": 18, \"building_type\": \"SLAB\", \"business_area\": \"彩虹城\", \"community_name\": \"之江公寓\", \"ownership_type\": \"COMMERCIAL\", \"property_usage\": \"RESIDENTIAL\", \"schema_version\": \"1.0\", \"layout_structure\": \"DUPLEX\", \"building_area_sqm\": 297.93, \"internal_area_sqm\": 236.15, \"construction_structure\": \"STEEL_CONCRETE\"}','c06495da4ad80b33fd13b289f460acba9d5a98792d4f52b9c3e33e6589cb4675','DEMO_ONLY','HISTORICAL_DEMO','LISTING_UNVERIFIED',38368.86,11431233.36,'{\"method\": \"SPLIT_CONFORMAL_LOG_UNIT_BY_COMMUNITY_SEEN\", \"nominal_coverage\": 0.9, \"calibration_group\": \"seen\", \"lower_total_price_yuan\": 9718231.18, \"upper_total_price_yuan\": 13446181.06, \"calibration_sample_count\": 2070}','BUSINESS_AREA',271,'[\"HISTORICAL_DATA\", \"PRICE_BASIS_UNVERIFIED\", \"BUSINESS_AREA_FALLBACK\"]','[\"参考样本数是训练集中同小区或同板块记录数，并非严格匹配的相似成交房源。\"]','historical-reference-v1','ce3f0cf611bd59f95acdad140c1dd7422761997c73ec3c2b903238a8df7dc214',NULL,'2026-10-23 13:35:57','基于历史挂牌样本的辅助定价演示；价格口径未核实，不代表当前市场价、未来价格或房地产评估报告。区间不保证覆盖实际成交价。','2026-10-23 13:35:57');
