DROP TABLE IF EXISTS `house_show`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `house_show` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '带看记录主键ID',
  `house_id` bigint NOT NULL COMMENT '关联房源ID',
  `customer_id` bigint DEFAULT NULL COMMENT '关联客户ID',
  `broker_id` bigint NOT NULL COMMENT '执行带看的经纪人ID',
  `completed_time` datetime DEFAULT NULL COMMENT '带看完成时间',
  `customer_name` varchar(64) DEFAULT NULL COMMENT '客户姓名（演示用）',
  `remark` text COMMENT '带看备注/回访记录',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `store_id` bigint DEFAULT NULL COMMENT '所属门店ID',
  `appointment_time` datetime DEFAULT NULL COMMENT '预约时间',
  `status` varchar(16) NOT NULL DEFAULT 'COMPLETED' COMMENT '带看状态',
  `cancel_reason` varchar(500) DEFAULT NULL COMMENT '取消原因',
  `feedback` text COMMENT '带看反馈',
  `intention` varchar(16) DEFAULT NULL COMMENT '客户意向',
  `follow_up_time` datetime DEFAULT NULL COMMENT '下次跟进时间',
  `data_origin` varchar(32) NOT NULL DEFAULT 'LEGACY_DEMO' COMMENT '数据来源',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否逻辑删除',
  `next_contact_at` datetime DEFAULT NULL,
  `show_time` datetime NOT NULL,
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_house` (`house_id`),
  KEY `idx_broker` (`broker_id`),
  KEY `idx_show_time` (`completed_time`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_showing_store_status` (`store_id`,`status`,`completed_time`),
  KEY `idx_showing_customer` (`customer_id`)
) ENGINE=InnoDB AUTO_INCREMENT=231 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='房源带看记录表（演示用）';
